import { numericChannelPrograms, type NumericChannelOutput } from '@wildshard/sdk/clientChannels';

export const BELLBACK_NATIVE_JOINTS = ['body', 'head', 'bell', 'clapper', 'leg0', 'leg1', 'leg2', 'leg3'];
// Exact Frame2 leg convex YZ support vertices, relative to each rigid leg joint.
// Generated by arena-candidate1/measure.py; all weighted vertices are checked by the envelope test.
const contacts: readonly (readonly (readonly [number, number])[])[] = [[[-1.4600000381469727, 0.04977816343307495], [-0.06750011444091797, -0.3382621705532074], [0.14750003814697266, -0.3382621705532074], [0.28249359130859375, -0.1452515423297882], [0.3402135372161865, 0.1452515721321106], [0.14750003814697266, 0.338262140750885], [-0.08629250526428223, 0.4215923547744751], [-1.3801184743642807, 0.8650383353233337], [-1.4600000381469727, 0.8102218508720398]], [[-1.4600000381469727, 0.04977816343307495], [-0.06750011444091797, -0.3382621705532074], [0.14750003814697266, -0.3382621705532074], [0.3659687042236328, 0.0], [0.21052706241607666, 0.24489402770996094], [0.14750003814697266, 0.338262140750885], [-0.04667472839355469, 0.40577369928359985], [-1.3801184743642807, 0.8650383353233337], [-1.4600000381469727, 0.8102218508720398]], [[-1.4600000381469727, -0.7302218675613403], [-1.1987882852554321, -0.6811466217041016], [-0.09199070930480957, -0.4431666135787964], [0.14750003814697266, -0.3382622003555298], [0.28249359130859375, -0.14525151252746582], [0.3402135372161865, 0.14525151252746582], [0.14750003814697266, 0.3382622003555298], [-0.19066071510314941, 0.40577366948127747], [-0.6609761118888855, 0.4174204468727112], [-1.380118414759636, 0.08503830432891846], [-1.4600000381469727, 0.03022181987762451]], [[-1.4600000381469727, -0.7302218675613403], [-1.1906937956809998, -0.6811466217041016], [-0.20798778533935547, -0.4431666135787964], [0.14750003814697266, -0.3382622003555298], [0.2171417474746704, -0.24206101894378662], [0.3659687042236328, 0.0], [0.21506571769714355, 0.2350219488143921], [0.14750003814697266, 0.3382622003555298], [-0.04667472839355469, 0.40577366948127747], [-0.6110979914665222, 0.4174204468727112], [-1.380118414759636, 0.08503830432891846], [-1.4600000381469727, 0.03022181987762451]]];
type Read = Parameters<NumericChannelOutput['expr']>[1];
type Builder = Parameters<NumericChannelOutput['expr']>[0];
function expression(b: Builder, r: Read) {
  const memo = new Map<number, number>();
  const n = (x: number) => { const old = memo.get(x); if (old !== undefined) return old; const v = b.constant(x); memo.set(x, v); return v; };
  const add = (a: number, c: number) => b.binary('add', a, c), sub = (a: number, c: number) => b.binary('sub', a, c);
  const mul = (a: number, c: number) => b.binary('mul', a, c), clamp = (a: number) => b.binary('max', n(0), b.binary('min', n(1), a));
  const smooth = (a: number) => { const x = clamp(a); return mul(mul(x,x), sub(n(3),mul(n(2),x))); };
  const dead = smooth(r('frame',['deathT'])), live = sub(n(1),dead);
  const step = r('scalars',['step']), clock = r('scalars',['clock']);
  const eq = (x: number) => b.binary('gt',n(.5),b.unary('abs',sub(step,n(x))));
  const ramp = (start: number, end: number) => clamp(b.binary('div',sub(clock,n(start)),n(end-start)));
  // These three strikes have no movement descriptor: their active phases are time-driven.
  const env = (state: number, wind: number, active: number, recovery: number) => ({
    get tell() { return mul(eq(state),mul(ramp(0,wind*.8),sub(n(1),ramp(wind,wind+active)))); },
    get hit() { return mul(eq(state),mul(ramp(wind,wind+active),sub(n(1),ramp(wind+active,wind+active+recovery)))); } });
  const gaits = new Map<number, number>();
  const bodyY = sub(r('frame',['dims','bodyY']),mul(n(.3),dead));
  return { n, add, sub, mul, dead, live, bodyY, env, eq, ramp,
    alive: (v: number) => mul(live,v), sin: (v: number) => b.unary('sin',v),
    idle: () => mul(live,b.unary('sin',mul(r('frame',['t']),n(1.6)))),
    flinch: () => mul(live,clamp(r('frame',['flinch']))),
    gait: (i: number) => { const old=gaits.get(i);if(old!==undefined)return old;const value=mul(mul(live,clamp(r('frame',['speed']))),mul(eq(0),b.unary('sin',add(mul(r('frame',['phase']),n(2*Math.PI)),n(i===0||i===3?0:Math.PI)))));gaits.set(i,value);return value; },
  };
}
/** New eight-joint native motion. Root flinch is authored exactly once. Leg support is local-pose
 * grounding only: engine ragdoll/root motion must still be checked in the actual arena. */
export function bellbackNativeClips(): { group: string; states: string[]; scalars: { name: string; path: string[]; fallback: number }[]; programs: ReturnType<typeof numericChannelPrograms> } {
  const outputs: NumericChannelOutput[]=[];
  const channel=(joint:string,property:'rotation'|'position',axis:'x'|'y'|'z',expr:NumericChannelOutput['expr']) => outputs.push({target:`joint.${joint}`,path:[property,axis],expr});
  channel('body','position','y',(b,r)=>expression(b,r).bodyY);
  channel('head','rotation','x',(b,r)=>{const e=expression(b,r);return e.add(e.mul(e.n(.035),e.idle()),e.add(e.mul(e.n(-.12),e.flinch()),e.mul(e.n(-.20),e.dead)));});
  channel('bell','rotation','x',(b,r)=>{const e=expression(b,r),a=e.env(1,1.2,.12,.2),c=e.env(2,.85,.15,.6);return e.add(e.alive(e.add(e.mul(e.n(-.14),a.tell),e.add(e.mul(e.n(.2),a.hit),e.add(e.mul(e.n(.12),c.tell),e.mul(e.n(-.2),c.hit))))),e.add(e.mul(e.n(.015),e.idle()),e.mul(e.n(.22),e.dead)));});
  channel('clapper','rotation','x',(b,r)=>{const e=expression(b,r),a=e.env(1,1.2,.12,.2),c=e.env(2,.85,.15,.6);return e.add(e.alive(e.add(e.mul(e.n(-.7),a.tell),e.add(e.mul(e.n(.5),a.hit),e.add(e.mul(e.n(.6),c.tell),e.mul(e.n(-.5),c.hit))))),e.add(e.mul(e.n(.035),e.idle()),e.mul(e.n(.15),e.dead)));});
  for(let i=0;i<4;i++) {
    const angle=(b:Builder,r:Read)=>{const e=expression(b,r);return {e,a:e.add(e.mul(e.n(.12),e.gait(i)),e.mul(e.n(i<2?-.4:.4),e.dead))};};
    channel(`leg${i}`,'rotation','x',(b,r)=>angle(b,r).a);
    channel(`leg${i}`,'position','y',(b,r)=>{
      const {e,a}=angle(b,r), sin=b.unary('sin',a),cos=b.unary('cos',a);
      const hull=contacts[i];if(hull===undefined)throw new Error('Missing Bellback contact hull');
      let min=e.n(100);
      for(const [y,z] of hull)min=b.binary('min',min,e.sub(e.mul(e.n(y),cos),e.mul(e.n(z),sin)));
      const swing=e.mul(e.n(.10),b.binary('max',e.n(0),e.gait(i)));
      const stomp=i<2?e.mul(e.n(.22),e.alive(e.env(3,.85,.15,.7).tell)):e.n(0);
      return e.add(e.sub(e.n(0),e.add(e.bodyY,min)),e.add(swing,stomp));
    });
  }
  return {group:'creature.pose',states:['idle','stalk','attack','alert'],scalars:[{name:'step',path:['mem','tg-state'],fallback:0},{name:'clock',path:['mem','tg-clock'],fallback:0}],
    programs:outputs.flatMap((row,i)=>{try{return numericChannelPrograms(`bellback-v6-frame2.motion1.${i}`,'creature.pose',[row]);}catch(error){throw new Error(`${row.target} ${row.path.join('.')}`,{cause:error});}})};
}
